export interface PlaybookStep {
  day: string;
  title: string;
  body: string;
  artifact?: string;
  // Atomic, citable single sentence summarizing this step. Renders as a pull
  // quote and is the sentence an LLM is most likely to lift into an answer.
  // Aim for 15-30 words, declarative, with at least one specific number or proper noun.
  directAnswer?: string;
}

export interface PlaybookFAQ {
  q: string;
  a: string;
}

export interface PlaybookStat {
  // 3 stat strip rendered above the steps. Use real, defensible math —
  // never invent numbers. If a stat is industry-typical not measured, say so
  // in the context line.
  label: string;
  value: string;
  context?: string;
}

// Long-form chapter for the master playbook. Each chapter body is markdown
// (GFM: tables, lists, blockquotes, code). Renders via react-markdown.
// Use blockquotes (>) for callout-style emphasis. Use tables for pricing,
// segments, math worksheets. Use code fences for templates and scripts.
export interface PlaybookChapter {
  number: number;            // 1, 2, 3 ...
  title: string;             // h2 title
  intro?: string;            // optional one-paragraph chapter intro
  markdown: string;          // the chapter body, GFM markdown
  takeaway?: string;         // optional "the one thing you must take from this chapter"
}

export interface Playbook {
  slug: string;
  niche: string;
  question: string;
  headline: string;
  hook: string;
  outcome: string;
  readTime: string;
  steps: PlaybookStep[];
  whyItFails: string;
  cta: string;
  scaffolded?: boolean;

  // Conversion + SEO fields. Optional — pages render without them but a
  // full conversion-grade page should fill all of them.
  subhead?: string;                  // 1-line agitation under H1, before the hook
  tldr?: string;                     // 2-3 sentence direct answer to the question, for GEO/AI citation. Renders with .tldr.direct-answer (matches speakable schema selectors).
  byTheNumbers?: PlaybookStat[];     // 3-stat strip — real math behind the outcome
  whatYoullLearn?: string[];         // 4-7 scannable takeaways
  whoFor?: string[];                 // 3-5 "this is for you if..." bullets
  whoNotFor?: string[];              // 2-3 "skip this if..." bullets — qualifier
  proofLine?: string;                // 1-line credibility ("written by X who did Y")
  midPageHook?: string;              // re-engagement hook before mid-page CTA
  faq?: PlaybookFAQ[];               // 5-7 FAQs — kills objections + serves SEO
  seoTitle?: string;                 // <title> override (default: headline)
  seoDescription?: string;           // <meta description> (155-160 chars)
  seoKeyword?: string;               // primary keyword for the post
  ogImage?: string;                  // absolute path under /public for og:image override
  datePublished?: string;            // ISO date - Article schema
  lastUpdated?: string;              // ISO date - Article schema (defaults to datePublished)

  // Master playbook structure: when present, the page renders chapters as
  // long-form content (markdown body) instead of (or alongside) the steps[]
  // structure. Used for the canonical /playbooks/2026-gtm-playbook.
  chapters?: PlaybookChapter[];
}

